    11	  requestUrl: string,
    12	  configuredUrl: string,
    13	  deploymentHosts: readonly (string | undefined)[] = [
    14	    process.env.VERCEL_URL,
    15	    process.env.VERCEL_BRANCH_URL,
    16	  ]
    17	): string {
    18	  const configured = new URL(configuredUrl).origin;
    19	  let request: URL;
    20	  try {
    21	    request = new URL(requestUrl);
    22	  } catch {
    23	    return configured;
    24	  }
    25	
    26	  const host = request.hostname;
    27	  const trusted =
    28	    request.origin === configured ||
    29	    host === "localhost" ||
    30	    host === "127.0.0.1" ||
    31	    deploymentHosts.some((own) => own && own.toLowerCase() === host);
    32	
