    48	      from: env.RESEND_FROM,
    49	      react: (
    50	        <ContactTemplate
    51	          email={input.email}
    52	          message={input.message}
    53	          name={input.name}
    54	          sentAt={new Date()}
    55	        />
    56	      ),
    57	      replyTo: input.email,
    58	      subject: `Contact form: ${input.name}`,
    59	      to: env.RESEND_FROM,
    60	    });
    61	
    62	    if (error) {
    63	      // Logged and reported with the provider's wording; the visitor gets
    64	      // a fixed line rather than an API message.
    65	      parseError(error);
    66	      return { error: MESSAGES.sendFailed };
    67	    }
    68	
    69	    return { success: true };
    70	  } catch (error) {
