     1	import arcjet, {
     2	  type ArcjetBotCategory,
     3	  type ArcjetWellKnownBot,
     4	  detectBot,
     5	  request,
     6	  shield,
     7	} from "@arcjet/next";
     8	import { keys } from "./keys";
     9	
    10	const arcjetKey = keys().ARCJET_KEY;
    11	
    12	export const secure = async (
    13	  allow: (ArcjetWellKnownBot | ArcjetBotCategory)[],
    14	  sourceRequest?: Request
    15	) => {
    16	  if (!arcjetKey) {
    17	    return;
    18	  }
    19	
    20	  const base = arcjet({
    21	    // Identify the user by their IP address
    22	    characteristics: ["ip.src"],
    23	    // Get your site key from https://app.arcjet.com
    24	    key: arcjetKey,
    25	    rules: [
    26	      // Protect against common attacks with Arcjet Shield
    27	      shield({
    28	        // Will block requests. Use "DRY_RUN" to log only
    29	        mode: "LIVE",
    30	      }),
    31	      // Other rules are added in different routes
    32	    ],
    33	  });
    34	
    35	  const req = sourceRequest ?? (await request());
    36	  const aj = base.withRule(detectBot({ allow, mode: "LIVE" }));
    37	  const decision = await aj.protect(req);
    38	
    39	  if (decision.isDenied()) {
    40	    if (decision.reason.isBot()) {
    41	      throw new Error("No bots allowed");
    42	    }
    43	
    44	    if (decision.reason.isRateLimit()) {
    45	      throw new Error("Rate limit exceeded");
    46	    }
    47	
    48	    throw new Error("Access denied");
    49	  }
    50	};
